1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	};
52	
53	const basePremiumOf = (items: Item[]): number =>
54	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
55	
56	const quote = (step: QuoteStep): StepResult => {
57	  const basePremium = basePremiumOf(step.items);
58	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
59	
60	  return {
61	    premium: Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE),
62	  };
63	};
64	
65	const runStep = (step: Step): StepResult => {
66	  switch (step.op) {
67	    case "quote":
68	      return quote(step);
69	    default:
70	      throw new Error(`Unsupported step: ${step.op}`);
71	  }
72	};
73	
74	export const runScenario = (scenario: Scenario): ScenarioResult => ({
75	  results: scenario.steps.map(runStep),
76	});
77

